#!/usr/bin/env bash
# Firm reason: 5 (thin compiler/host-compiler wrapper; all app and update rules are Coax).
set -euo pipefail
mkdir -p apps/openagents-ios/Generated apps/openagents-ios/Starter/build
"${COAX:-coax/bin/coax}" c coax/native/updates-policy.coax --library --header apps/openagents-ios/Generated/NativePolicy.h > apps/openagents-ios/Generated/NativePolicy.c
"${COAX:-coax/bin/coax}" c coax/native/updates-wire.coax --library --header apps/openagents-ios/Generated/NativeWire.h > apps/openagents-ios/Generated/NativeWire.c
"${COAX:-coax/bin/coax}" c metaverse/phone-signin.coax --library --header apps/openagents-ios/Generated/PhoneSignin.h > apps/openagents-ios/Generated/PhoneSignin.c
"${COAX:-coax/bin/coax}" c pay/wallet-balance-wire.coax --library --header apps/openagents-ios/Generated/WalletBalance.h > apps/openagents-ios/Generated/WalletBalance.c
"${COAX:-coax/bin/coax}" c components/layout/native-composer.coax --library --header apps/openagents-ios/Generated/NativeComposer.h > apps/openagents-ios/Generated/NativeComposer.c
# The book's first milestone (#13516): the shared app the website runs at /milestone too.
"${COAX:-coax/bin/coax}" c apps/shared/openagents-app.coax --library --header apps/openagents-ios/Generated/OpenagentsApp.h > apps/openagents-ios/Generated/OpenagentsApp.c
coax/web/tool.sh coax/native/runtime.coax apps/openagents-ios/Generated/runtime.txt apps/shared/native/NativeHost.swift apps/shared/native/NativeProgram.swift apps/shared/native/NativeControls.swift apps/shared/native/NativeComposer.swift components/fonts/DMSans-Regular.ttf components/fonts/DMSans-Medium.ttf apps/openagents-ios/Generated/NativeComposer.c apps/shared/native/NativeUpdates.swift apps/shared/host/apple/AppAuth.swift apps/shared/host/apple/DeviceKey.swift apps/openagents-ios/OpenAgents/SignIn/PhoneSignIn.swift apps/openagents-ios/OpenAgents/SignIn/NostrKey.swift apps/openagents-ios/NativeBridge.h apps/openagents-ios/StarterApp.swift apps/openagents-ios/OpenAgents/Info.plist apps/openagents-ios/OpenAgents/OpenAgents.entitlements apps/openagents-ios/OpenAgents/Platform/NostrSign.c apps/openagents-ios/OpenAgents/Platform/NostrSign.h apps/openagents-ios/project.yml coax/native/openagents-public-key.txt apps/openagents-ios/Generated/NativePolicy.c apps/openagents-ios/Generated/NativeWire.c apps/openagents-ios/Generated/PhoneSignin.c apps/openagents-ios/Generated/WalletBalance.c apps/openagents-ios/OpenAgents/Wallet/SparkHost.swift apps/openagents-ios/OpenAgents/Wallet/WalletKeychain.swift apps/openagents-ios/OpenAgents/Wallet/BIP39.swift apps/openagents-ios/OpenAgents/Wallet/BreezKey.swift apps/openagents-ios/OpenAgents/Resources/bip39-english.txt apps/openagents-ios/OpenAgents.xcodeproj/project.xcworkspace/xcshareddata/swiftpm/Package.resolved apps/openagents-ios/OpenAgents/Shared/SharedAppViewController.swift apps/openagents-ios/OpenAgents/Shared/OpenagentsAppUnit.c apps/shared/host/apple/phone-drive.c apps/shared/host/apple/phone-drive.h apps/shared/host/drive.c apps/openagents-ios/Generated/OpenagentsApp.c
coax/web/wasm.sh apps/openagents-ios/home/app.coax apps/openagents-ios/home/face.c apps/openagents-ios/Starter/build/app.wasm
coax/web/wasm.sh apps/openagents-ios/extras/app.coax coax/native/starter/face.c apps/openagents-ios/Starter/build/extras.wasm
coax/web/tool.sh coax/native/prepare.coax "$@"
